export function matchIngredient(name) {
  if (!name) return null;
  const n = name.toLowerCase().trim();
  let hit = INGREDIENT_DB.find(i => i.id === n || i.name.toLowerCase() === n);
  if (hit) return hit;
  hit = INGREDIENT_DB.find(i => (i.aliases||[]).some(a => a.toLowerCase() === n));
  if (hit) return hit;
  hit = INGREDIENT_DB.find(i => n.includes(i.name.toLowerCase()) || i.name.toLowerCase().includes(n) || (i.aliases||[]).some(a => n.includes(a.toLowerCase())));
  return hit || null;
}
export function searchIngredients(query, limit = 8) {
  if (!query) return [];
  const q = query.toLowerCase();
  return INGREDIENT_DB.filter(i => i.name.toLowerCase().includes(q) || (i.aliases||[]).some(a => a.toLowerCase().includes(q))).slice(0, limit);
}
export function estimateFromDb(ingredients) {
  const totals = { calories:0, protein:0, carbs:0, fat:0, fiber:0, sodium:0, calcium:0, iron:0, potassium:0, vitaminA:0, vitaminC:0, vitaminD:0, vitaminB12:0, costCents:0, matched:0, unmatched:[] };
  (ingredients||[]).forEach(ing => {
    const db = matchIngredient(ing.name);
    if (!db) { totals.unmatched.push(ing.name); return; }
    totals.matched++;
    const grams = (ing.qty||1) * (db.gramsPerUnit||100);
    const factor = grams / 100;
    Object.keys(db.per100g).forEach(k => { totals[k] = (totals[k]||0) + db.per100g[k] * factor; });
    totals.costCents += (db.centsPerUnit||0) * (ing.qty||1);
  });
  Object.keys(totals).forEach(k => { if (typeof totals[k]==='number') totals[k] = Math.round(totals[k]); });
  return totals;
}
